import { generatePreviewAlias } from "@cloudflare/deploy-helpers";
import {
	DEFAULT_COMPAT_DATE,
	getCIGeneratePreviewAlias,
	getCIOverrideName,
	getWranglerTmpDir,
	UserError,
} from "@cloudflare/workers-utils";
import {
	getAssetsOptions,
	validateAssetsArgsAndConfig,
	validateAssetsOptions,
} from "../assets";
import { getNormalizedContainerOptions } from "../containers/config";
import { getFlag } from "../experimental-flags";
import { logger } from "../logger";
import { getMetricsUsageHeaders } from "../metrics";
import { getSiteAssetPaths } from "../sites";
import { requireAuth } from "../user";
import { collectKeyValues } from "../utils/collectKeyValues";
import { getScriptName } from "../utils/getScriptName";
import { resolveDurableObjectsCodeUpdateStrategy } from "../versions/deployment-args";
import { getEntry } from "./entry";
import { applyZoneArgsToRoutes } from "./route-zone-args";
import type { HandlerArgs } from "../core/types";
import type { DeployArgs } from "../deploy/index";
import type { VersionsUploadArgs } from "../versions/upload";
import type { sharedDeployVersionsArgs } from "./deploy-args";
import type { BuildProps } from "./maybe-build-worker";
import type {
	DeployProps,
	SharedDeployVersionsProps,
	VersionsUploadProps,
} from "@cloudflare/deploy-helpers";
import type { AssetsOptions } from "@cloudflare/workers-utils";
import type { EphemeralDirectory } from "@cloudflare/workers-utils";
import type { Config } from "@cloudflare/workers-utils";

type SharedArgs = HandlerArgs<typeof sharedDeployVersionsArgs>;

async function mergeSharedConfigArgs(
	command: "deploy" | "versions upload",
	args: SharedArgs,
	config: Config
): Promise<{ shared: SharedDeployVersionsProps; buildProps: BuildProps }> {
	const entry = await getEntry(args, config, command);

	validateAssetsArgsAndConfig(args, config);

	const assetsDir = validateAssetsOptions({ args, config });

	let name = getScriptName(args, config);

	const ciOverrideName = getCIOverrideName();
	if (ciOverrideName !== undefined && ciOverrideName !== name) {
		logger.warn(
			`Failed to match Worker name. Your config file is using the Worker name "${name}", but the CI system expected "${ciOverrideName}". Overriding using the CI provided Worker name. Workers Builds connected builds will attempt to open a pull request to resolve this config name mismatch.`
		);
		name = ciOverrideName;
	}

	const compatibilityDate = args.latest
		? DEFAULT_COMPAT_DATE
		: (args.compatibilityDate ?? config.compatibility_date);

	const compatibilityFlags =
		args.compatibilityFlags ?? config.compatibility_flags;

	const noBundle = !(args.bundle ?? !config.no_bundle);

	const dryRun = args.dryRun ?? false;
	const accountId = dryRun ? undefined : await requireAuth(config);

	const metricsHeaders = await getMetricsUsageHeaders(config.send_metrics);
	const sendMetrics = metricsHeaders !== undefined;

	const uploadSourceMaps = args.uploadSourceMaps ?? config.upload_source_maps;

	const shared: SharedDeployVersionsProps = {
		entry,
		name,
		compatibilityDate,
		compatibilityFlags,
		assetsDir,
		main: args.script ?? config.main,
		keepVars: Boolean(args.keepVars || config.keep_vars),
		isWorkersSite: Boolean(args.site || config.site),
		dryRun,
		env: args.env,
		outfile: args.outfile,
		tag: args.tag,
		message: args.message,
		secretsFile: args.secretsFile,
		cliVars: collectKeyValues(args.var),
		experimentalAutoCreate: args.experimentalAutoCreate,
		accountId,
		sendMetrics,
		resourcesProvision: getFlag("RESOURCES_PROVISION") ?? false,
		skipProvisioningConfigWriteback: false,
		strict: args.strict ?? false,
		containers: {
			source: config.containers,
			standard: { normalized: [], builtImages: [] },
			durableObjects: { builtImages: [] },
		},
	};

	const buildProps: BuildProps = {
		entry,
		name,
		compatibilityDate,
		compatibilityFlags,
		uploadSourceMaps,
		jsxFactory: args.jsxFactory || config.jsx_factory,
		jsxFragment: args.jsxFragment || config.jsx_fragment,
		tsconfig: args.tsconfig ?? config.tsconfig,
		minify: args.minify ?? config.minify,
		noBundle,
		defines: { ...config.define, ...collectKeyValues(args.define) },
		alias: { ...config.alias, ...collectKeyValues(args.alias) },
		doBindings: config.durable_objects.bindings,
		workflowBindings: config.workflows ?? [],
		destination: args.outdir ?? getWranglerTmpDir(entry.projectRoot, "deploy"),
		outdir: args.outdir,
		// Deploy-only; set by mergeDeployConfigArgs.
		metafile: undefined,
	};

	return { shared, buildProps };
}

export async function mergeDeployConfigArgs(
	args: DeployArgs,
	config: Config
): Promise<{ props: DeployProps; buildProps: BuildProps }> {
	const { shared, buildProps } = await mergeSharedConfigArgs(
		"deploy",
		args,
		config
	);

	const domainRoutes = (args.domains || []).map((domain) => ({
		pattern: domain,
		custom_domain: true as const,
	}));
	const routes = args.routes
		? applyZoneArgsToRoutes(args.routes, args)
		: (config.routes ?? (config.route ? [config.route] : []));
	const normalizedContainerConfig = await getNormalizedContainerOptions(
		config,
		{
			containersRollout: args.containersRollout,
			dryRun: shared.dryRun,
		}
	);

	return {
		props: {
			...shared,
			command: "deploy",
			legacyAssetPaths: getSiteAssetPaths(
				config,
				args.site,
				args.siteInclude,
				args.siteExclude
			),
			triggers: args.triggers ?? config.triggers?.crons,
			routes: [...routes, ...domainRoutes],
			logpush: args.logpush !== undefined ? args.logpush : config.logpush,
			dispatchNamespace: args.dispatchNamespace,
			oldAssetTtl: args.oldAssetTtl,
			containersRollout: args.containersRollout,
			durableObjectsCodeUpdateStrategy: resolveDurableObjectsCodeUpdateStrategy(
				args.durableObjectsCodeUpdateMode,
				config.durable_objects.code_update_strategy
			),
			containers: {
				...shared.containers,
				standard: {
					normalized: normalizedContainerConfig,
					builtImages: [],
				},
			},
		},
		buildProps: { ...buildProps, metafile: args.metafile },
	};
}

export async function mergeVersionsUploadConfigArgs(
	args: VersionsUploadArgs,
	config: Config
): Promise<{ props: VersionsUploadProps; buildProps: BuildProps }> {
	if (args.site || config.site) {
		throw new UserError(
			"Workers Sites does not support uploading versions through `wrangler versions upload`. You must use `wrangler deploy` instead.",
			{ telemetryMessage: "versions upload sites unsupported" }
		);
	}

	const { shared, buildProps } = await mergeSharedConfigArgs(
		"versions upload",
		args,
		config
	);

	const previewAlias =
		args.previewAlias ??
		(getCIGeneratePreviewAlias() === "true"
			? generatePreviewAlias(shared.name ?? "")
			: undefined);

	return {
		props: {
			...shared,
			command: "versions upload",
			previewAlias,
		},
		buildProps,
	};
}

export function cleanupDestination(
	destination: string | EphemeralDirectory
): void {
	if (typeof destination !== "string") {
		destination.remove();
	}
}

/**
 * Get the inputs for the standalone
 * `wrangler build --experimental-cf-build-output` path.
 */
export async function mergeBuildOutputProps(config: Config): Promise<{
	buildProps: BuildProps | undefined;
	assetsOptions: AssetsOptions | undefined;
}> {
	const assetsOptions = getAssetsOptions({
		args: { assets: undefined },
		config,
	});
	const isAssetsOnly =
		assetsOptions !== undefined &&
		assetsOptions.routerConfig.has_user_worker === false;

	if (isAssetsOnly) {
		return { buildProps: undefined, assetsOptions };
	}

	const entry = await getEntry({}, config, "deploy");
	const buildProps: BuildProps = {
		entry,
		name: config.name,
		compatibilityDate: config.compatibility_date,
		compatibilityFlags: config.compatibility_flags,
		uploadSourceMaps: config.upload_source_maps,
		jsxFactory: config.jsx_factory,
		jsxFragment: config.jsx_fragment,
		tsconfig: config.tsconfig,
		minify: config.minify,
		noBundle: config.no_bundle ?? false,
		defines: { ...config.define },
		alias: { ...config.alias },
		doBindings: config.durable_objects.bindings,
		workflowBindings: config.workflows ?? [],
		destination: getWranglerTmpDir(entry.projectRoot, "build"),
		outdir: undefined,
		metafile: undefined,
	};

	return { buildProps, assetsOptions };
}

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { validateNodeCompatMode } from "@cloudflare/deploy-helpers";
import { logger } from "../logger";
import { isNavigatorDefined } from "../navigator-user-agent";
import { bundleWorker } from "./bundle";
import { logBuildOutput } from "./esbuild-plugins/log-build-output";
import {
	createModuleCollector,
	getWrangler1xLegacyModuleReferences,
} from "./module-collection";
import { noBundleWorker } from "./no-bundle-worker";
import { loadSourceMaps } from "./source-maps";
import type { WorkerBuildResult } from "@cloudflare/deploy-helpers";
import type {
	CfModule,
	Config,
	DurableObjectBindings,
	EphemeralDirectory,
	Entry,
	WorkflowBinding,
} from "@cloudflare/workers-utils";

/**
 * The subset of merged config/args needed to build (bundle) a Worker.
 *
 * Building now happens separately from deploy/versions-upload, so these props
 * are passed only to `buildWorker` — not to `deploy()` / `versionsUpload()`.
 */
export type BuildProps = {
	/** Merged from args.script/config.main/config.site.entry-point/config.assets. */
	entry: Entry;
	/** Merged: --name arg ?? config.name, with CI override applied. Used for the outdir README. */
	name: string | undefined;
	/** Merged: --compatibility-date arg ?? config.compatibility_date. */
	compatibilityDate: string | undefined;
	/** Merged: --compatibility-flags arg ?? config.compatibility_flags. */
	compatibilityFlags: string[];
	/** Merged: --upload-source-maps arg ?? config.upload_source_maps. */
	uploadSourceMaps: boolean | undefined;
	/** Merged: --jsx-factory arg || config.jsx_factory. */
	jsxFactory: string;
	/** Merged: --jsx-fragment arg || config.jsx_fragment. */
	jsxFragment: string;
	/** Merged: --tsconfig arg ?? config.tsconfig. */
	tsconfig: string | undefined;
	/** Merged: --minify arg ?? config.minify. */
	minify: boolean | undefined;
	/** Merged: !(--bundle arg ?? !config.no_bundle). */
	noBundle: boolean;
	/** Merged: { ...config.define, ...--define arg }. CLI overrides config. */
	defines: Record<string, string>;
	/** Merged: { ...config.alias, ...--alias arg }. CLI overrides config. */
	alias: Record<string, string>;
	/**
	 * Durable Object bindings for post-build class-export validation.
	 */
	doBindings: DurableObjectBindings;
	/** Workflow bindings for post-build class-export validation. */
	workflowBindings: WorkflowBinding[];
	/** Output directory for the bundled Worker. From --outdir arg or a temp directory. */
	destination: string | EphemeralDirectory;
	/** From --outdir arg. Used for the outdir README and noBundleWorker. */
	outdir: string | undefined;
	/** From --metafile arg. Deploy-only; undefined for versions upload. */
	metafile: string | boolean | undefined;
};

export async function buildWorker(
	props: BuildProps,
	config: Config
): Promise<WorkerBuildResult> {
	const nodejsCompatMode = validateNodeCompatMode(
		props.compatibilityDate,
		props.compatibilityFlags,
		{ noBundle: props.noBundle }
	);

	if (props.noBundle && props.minify) {
		logger.warn(
			"`--minify` and `--no-bundle` can't be used together. If you want to minify your Worker and disable Wrangler's bundling, please minify as part of your own bundling process."
		);
	}
	const {
		entry,
		noBundle,
		destination,
		uploadSourceMaps,
		jsxFactory,
		jsxFragment,
		minify,
		compatibilityDate,
		compatibilityFlags,
	} = props;

	if (props.outdir) {
		// we're using a custom output directory,
		// so let's first ensure it exists
		mkdirSync(props.outdir, { recursive: true });
		const readmePath = path.join(props.outdir, "README.md");
		writeFileSync(
			readmePath,
			`This folder contains the built output assets for the worker "${props.name}" generated at ${new Date().toISOString()}.`
		);
	}

	if (noBundle) {
		// if we're not building, let's just copy the entry to the destination directory
		const destinationDir =
			typeof destination === "string" ? destination : destination.path;
		mkdirSync(destinationDir, { recursive: true });
		writeFileSync(
			path.join(destinationDir, path.basename(entry.file)),
			readFileSync(entry.file, "utf-8")
		);
	}

	const entryDirectory = path.dirname(entry.file);
	const moduleCollector = createModuleCollector({
		wrangler1xLegacyModuleReferences: getWrangler1xLegacyModuleReferences(
			entryDirectory,
			entry.file
		),
		entry,
		// `moduleCollector` doesn't get used when `noBundle` is set, so
		// `findAdditionalModules` always defaults to `false`
		findAdditionalModules: config.find_additional_modules ?? false,
		rules: config.rules ?? [],
		preserveFileNames: config.preserve_file_names ?? false,
	});

	const {
		modules,
		dependencies,
		resolvedEntryPointPath,
		bundleType,
		...bundle
	} = noBundle
		? await noBundleWorker(
				entry,
				config.rules ?? [],
				props.outdir,
				config.python_modules.exclude,
				config.find_additional_modules
			)
		: await bundleWorker(
				entry,
				typeof destination === "string" ? destination : destination.path,
				{
					metafile: props.metafile,
					bundle: true,
					additionalModules: [],
					moduleCollector,
					doBindings: props.doBindings,
					workflowBindings: props.workflowBindings,
					jsxFactory,
					jsxFragment,
					tsconfig: props.tsconfig,
					minify,
					keepNames: config.keep_names ?? true,
					sourcemap: uploadSourceMaps,
					nodejsCompatMode,
					compatibilityDate,
					compatibilityFlags,
					define: props.defines,
					checkFetch: false,
					alias: props.alias,
					// We want to know if the build is for development or publishing
					// This could potentially cause issues as we no longer have identical behaviour between dev and deploy?
					targetConsumer: "deploy",
					local: false,
					projectRoot: entry.projectRoot,
					defineNavigatorUserAgent: isNavigatorDefined(
						compatibilityDate,
						compatibilityFlags
					),
					plugins: [logBuildOutput(nodejsCompatMode)],

					// Pages specific options used by wrangler pages commands
					entryName: undefined,
					inject: undefined,
					isOutfile: undefined,
					external: undefined,

					// These options are dev-only
					testScheduled: undefined,
					watch: undefined,
				}
			);

	// Add modules to dependencies for size warning
	for (const module of modules) {
		const modulePath =
			module.filePath === undefined
				? module.name
				: path.relative("", module.filePath);
		const bytesInOutput =
			typeof module.content === "string"
				? Buffer.byteLength(module.content)
				: module.content.byteLength;
		dependencies[modulePath] = { bytesInOutput };
	}

	const content = readFileSync(resolvedEntryPointPath, {
		encoding: "utf-8",
	});
	const main: CfModule = {
		name: path.basename(resolvedEntryPointPath),
		filePath: resolvedEntryPointPath,
		content,
		type: bundleType,
	};
	const sourceMaps = uploadSourceMaps
		? loadSourceMaps(main, modules, bundle)
		: undefined;

	return {
		modules,
		sourceMaps,
		dependencies,
		resolvedEntryPointPath,
		bundleType,
		content,
	};
}

import fs from "node:fs";
import path from "node:path";
import { onExit } from "signal-exit";
import { removeDirSync } from "./fs-helpers";

/**
 * A short-lived directory. Automatically removed when the process exits, but
 * can be removed earlier by calling `remove()`.
 */
export interface EphemeralDirectory {
	path: string;
	remove(): void;
}

/**
 * Gets the path to the project's `.wrangler` folder.
 */
export function getWranglerHiddenDirPath(
	projectRoot: string | undefined
): string {
	projectRoot ??= process.cwd();
	return path.join(projectRoot, ".wrangler");
}

/**
 * Maximum age of a `.wrangler/tmp/*` entry before we treat it as orphaned and
 * eligible for the startup sweep. Tuned to avoid touching any directory a
 * concurrent wrangler session might still own.
 */
const STALE_WRANGLER_TMP_DIR_MS = 24 * 60 * 60 * 1000;

/**
 * Tracks tmp roots already swept by this process so repeated
 * `getWranglerTmpDir` calls within one wrangler invocation only scan once.
 */
const sweptTmpRoots = new Set<string>();

/**
 * Removes stale `.wrangler/tmp/*` entries left behind by previous wrangler
 * sessions that exited abnormally (SIGKILL, OOM, host crash) and so missed
 * the `signal-exit` cleanup. Runs at most once per tmp root per process.
 *
 * Exported for tests.
 */
export function sweepStaleWranglerTmpDirs(tmpRoot: string): void {
	if (sweptTmpRoots.has(tmpRoot)) {
		return;
	}
	sweptTmpRoots.add(tmpRoot);

	let entries: fs.Dirent[];
	try {
		entries = fs.readdirSync(tmpRoot, { withFileTypes: true });
	} catch {
		return;
	}

	const cutoff = Date.now() - STALE_WRANGLER_TMP_DIR_MS;
	for (const entry of entries) {
		if (!entry.isDirectory()) {
			continue;
		}
		const entryPath = path.join(tmpRoot, entry.name);
		try {
			if (fs.statSync(entryPath).mtimeMs < cutoff) {
				removeDirSync(entryPath);
			}
		} catch {
			/* best effort - another process may have removed it first */
		}
	}
}

/**
 * Gets a temporary directory in the project's `.wrangler` folder with the
 * specified prefix. We create temporary directories in `.wrangler` as opposed
 * to the OS's temporary directory to avoid issues with different drive letters
 * on Windows. For example, when `esbuild` outputs a file to a different drive
 * than the input sources, the generated source maps are incorrect.
 */
export function getWranglerTmpDir(
	projectRoot: string | undefined,
	prefix: string,
	cleanup = true
): EphemeralDirectory {
	const tmpRoot = path.join(getWranglerHiddenDirPath(projectRoot), "tmp");
	fs.mkdirSync(tmpRoot, { recursive: true });
	sweepStaleWranglerTmpDirs(tmpRoot);

	const tmpPrefix = path.join(tmpRoot, `${prefix}-`);
	const tmpDir = fs.realpathSync(fs.mkdtempSync(tmpPrefix));

	const cleanupDir = () => {
		if (cleanup) {
			try {
				removeDirSync(tmpDir);
			} catch {
				/* best effort */
			}
		}
	};
	const removeExitListener = onExit(cleanupDir);

	return {
		path: tmpDir,
		remove() {
			removeExitListener();
			cleanupDir();
		},
	};
}

import path from "node:path";
import {
	configFileName,
	DEFAULT_COMPAT_DATE,
	formatConfigSnippet,
	UserError,
} from "@cloudflare/workers-utils";
import dedent from "ts-dedent";
import { sniffUserAgent } from "../package-manager";
import { guessWorkerFormat } from "./guess-worker-format";
import {
	resolveEntryWithAssets,
	resolveEntryWithEntryPoint,
	resolveEntryWithMain,
	resolveEntryWithScript,
} from "./resolve-entry";
import { runCustomBuild } from "./run-custom-build";
import type {
	Config,
	DurableObjectBindings,
	Entry,
	RawConfig,
} from "@cloudflare/workers-utils";

/**
 * Compute the entry-point for the Worker.
 */
export async function getEntry(
	args: {
		script?: string;
		moduleRoot?: string;
		assets?: string | undefined;
	},
	config: Config,
	command: "dev" | "deploy" | "versions upload" | "types"
): Promise<Entry> {
	const entryPoint = config.site?.["entry-point"];

	let paths:
		| { absolutePath: string; relativePath: string; projectRoot?: string }
		| undefined;

	if (args.script) {
		paths = resolveEntryWithScript(args.script);
	} else if (config.main !== undefined) {
		paths = resolveEntryWithMain(config.main, config);
	} else if (entryPoint) {
		paths = resolveEntryWithEntryPoint(entryPoint, config);
	} else if (args.assets || config.assets) {
		paths = resolveEntryWithAssets();
	} else {
		if (config.pages_build_output_dir && command === "dev") {
			throw new UserError(
				"It looks like you've run a Workers-specific command in a Pages project.\n" +
					"For Pages, please run `wrangler pages dev` instead.",
				{ telemetryMessage: "worker entry pages project command mismatch" }
			);
		}

		const compatibilityDateStr = DEFAULT_COMPAT_DATE;

		const updateConfigMessage = (snippet: RawConfig) => dedent`
			${
				config.configPath
					? `add the following to your "${configFileName(config.configPath)}" file:`
					: `create a "wrangler.jsonc" file containing:`
			}

			\`\`\`
			${formatConfigSnippet(
				{
					...(config.name ? {} : { name: "worker-name" }),
					...(config.compatibility_date
						? {}
						: { compatibility_date: compatibilityDateStr }),
					...snippet,
				},
				config.configPath
			)}
			\`\`\`

			`;

		const fullCommand = `${getNpxEquivalent()} wrangler ${command}`;
		throw new UserError(
			dedent`
			Missing entry-point to Worker script or to assets directory

			If there is code to deploy, you can either:
			- Specify an entry-point to your Worker script via the command line (ex: \`${fullCommand} src/index.ts\`)
			- Or ${updateConfigMessage({ main: "src/index.ts" })}

			If are uploading a directory of assets, you can either:
			- Specify the path to the directory of assets via the command line: (ex: \`${fullCommand} --assets=./dist\`)
			- Or ${updateConfigMessage({ assets: { directory: "./dist" } })}`,
			{ telemetryMessage: "missing worker entrypoint or assets directory" }
		);
	}
	await runCustomBuild(
		paths.absolutePath,
		paths.relativePath,
		config.build,
		config.configPath,
		{ wranglerCommand: command }
	);

	const projectRoot = paths.projectRoot ?? process.cwd();
	const { format, exports } = await guessWorkerFormat(
		paths.absolutePath,
		projectRoot,
		config.tsconfig
	);

	const { localBindings } = partitionDurableObjectBindings(config);

	if (format === "service-worker") {
		if (localBindings.length > 0) {
			const errorMessage =
				"You seem to be trying to use Durable Objects in a Worker written as a service-worker.";
			const addScriptName = `You can use Durable Objects defined in other Workers by specifying a \`script_name\` in your ${configFileName(config.configPath)} file, where \`script_name\` is the name of the Worker that implements that Durable Object. For example:`;
			const addScriptNameExamples =
				generateAddScriptNameExamples(localBindings);
			const migrateText =
				"Alternatively, migrate your worker to ES Module syntax to implement a Durable Object in this Worker:";
			const migrateUrl =
				"https://developers.cloudflare.com/workers/learning/migrating-to-module-workers/";
			throw new UserError(
				`${errorMessage}\n${addScriptName}\n${addScriptNameExamples}\n${migrateText}\n${migrateUrl}`,
				{ telemetryMessage: "tried to use DO with service worker" }
			);
		}
		if (config.migrations?.length) {
			const errorMessage =
				"Durable Object migrations require ES Module format Workers, but yours is being built as service-worker format. Migrations cannot be applied to service-worker format Workers.";
			const migrateText =
				'To use Durable Object migrations, deploy in ES Module format by adding a default export handler (e.g. "export default { fetch() {} }"), or remove "migrations" from your config if you don\'t need them. See:';
			const migrateUrl =
				"https://developers.cloudflare.com/workers/learning/migrating-to-module-workers/";
			throw new UserError(`${errorMessage}\n${migrateText}\n${migrateUrl}`, {
				telemetryMessage:
					"durable object migrations unsupported service worker",
			});
		}
	}

	return {
		file: paths.absolutePath,
		projectRoot,
		configPath: config.configPath,
		format,
		moduleRoot:
			args.moduleRoot ?? config.base_dir ?? path.dirname(paths.absolutePath),
		name: config.name ?? "worker",
		exports,
	};
}

/**
 * Groups the durable object bindings into two lists:
 * those that are defined locally and those that refer to a durable object defined in another script.
 */
export function partitionDurableObjectBindings(config: Config): {
	localBindings: DurableObjectBindings;
	remoteBindings: DurableObjectBindings;
} {
	const localBindings: DurableObjectBindings = [];
	const remoteBindings: DurableObjectBindings = [];
	for (const binding of config.durable_objects.bindings) {
		if (
			binding.script_name === undefined ||
			binding.script_name === config.name
		) {
			localBindings.push(binding);
		} else {
			remoteBindings.push(binding);
		}
	}
	return { localBindings, remoteBindings };
}

/**
 * Generates some help text based on the Durable Object bindings in a given
 * config indicating how the user can add a `script_name` field to bind an
 * externally defined Durable Object.
 */
function generateAddScriptNameExamples(
	localBindings: DurableObjectBindings
): string {
	function exampleScriptName(binding_name: string): string {
		return `${binding_name.toLowerCase().replaceAll("_", "-")}-worker`;
	}

	return localBindings
		.map(({ name, class_name }) => {
			const script_name = exampleScriptName(name);
			const currentBinding = `{ name = ${name}, class_name = ${class_name} }`;
			const fixedBinding = `{ name = ${name}, class_name = ${class_name}, script_name = ${script_name} }`;

			return `${currentBinding} ==> ${fixedBinding}`;
		})
		.join("\n");
}

export function getNpxEquivalent() {
	switch (sniffUserAgent()) {
		case "pnpm":
			return "pnpm";
		case "yarn":
			return "yarn";
		case "npm":
		default:
			return "npx";
	}
}

